style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-black: #02050a;
  --my-blue: #0077ff;
  --my-cyan: #00d9ff;
  --my-glass: rgba(0, 35, 65, .42);
  --my-text: #d9f5ff;
}

/* MAIN INTERFACE */
html,
body,
ytd-app,
#content,
#page-manager {
  background: #02050a !important;
  color: var(--my-text) !important;
}

/* TOP COMMAND BAR */
ytd-masthead,
#masthead-container {
  background: rgba(2, 8, 16, .97) !important;
  border-bottom: 1px solid #008cff66 !important;
  box-shadow: 0 4px 25px #0077ff22 !important;
}

/* HITANSHTUBE LOGO */
ytd-topbar-logo-renderer #logo-icon,
ytd-topbar-logo-renderer #logo-icon-container {
  display: none !important;
}

ytd-topbar-logo-renderer a#logo::after {
  content: "HitanshTube" !important;
  display: inline-block !important;
  color: #d9f5ff !important;
  font-size: 22px !important;
  font-weight: 800 !important;
  letter-spacing: 1px !important;
  text-shadow: 0 0 8px #00bfff,
               0 0 20px #0077ff !important;
}

/* SEARCH INTERFACE */
ytd-searchbox #container {
  background: rgba(0, 24, 45, .85) !important;
  border: 1px solid #008cff88 !important;
  border-radius: 10px !important;
  box-shadow: 0 0 14px #0077ff22 !important;
}

ytd-searchbox input {
  color: white !important;
}

/* SIDEBAR */
#guide-content,
ytd-mini-guide-renderer {
  background: #030912 !important;
  border-right: 1px solid #008cff33 !important;
}

ytd-guide-entry-renderer {
  border-radius: 10px !important;
  margin: 3px 7px !important;
}

ytd-guide-entry-renderer:hover {
  background: #0077ff22 !important;
  box-shadow: inset 3px 0 #00d9ff !important;
}

ytd-guide-entry-renderer[active] {
  background: #0077ff30 !important;
  border-left: 3px solid #00d9ff !important;
}

/* VIDEO CARDS */
ytd-rich-item-renderer,
ytd-video-renderer {
  background: transparent !important;
}

ytd-thumbnail {
  border: 1px solid #008cff55 !important;
  border-radius: 12px !important;
  overflow: hidden !important;
  transition: .25s ease !important;
}

ytd-rich-item-renderer:hover ytd-thumbnail {
  border-color: #00d9ff !important;
  box-shadow: 0 0 20px #0077ff66 !important;
}

/* VIDEO TITLES */
#video-title {
  color: #d9f5ff !important;
}

ytd-rich-item-renderer:hover #video-title {
  color: #00d9ff !important;
}

/* CATEGORY CHIPS */
yt-chip-cloud-chip-renderer {
  background: #071728 !important;
  border: 1px solid #087eaa66 !important;
  border-radius: 8px !important;
}

yt-chip-cloud-chip-renderer:hover {
  background: #00365b !important;
  border-color: #00d9ff !important;
  box-shadow: 0 0 12px #0077ff44 !important;
}

/* POPUP PANELS */
ytd-popup-container,
ytd-menu-popup-renderer {
  background: #061322 !important;
  border: 1px solid #008cff66 !important;
  border-radius: 12px !important;
  box-shadow: 0 0 22px #0077ff33 !important;
}

/* METADATA */
#channel-name,
#metadata-line {
  color: #759bb8 !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
  width: 6px !important;
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(#0077ff, #00d9ff) !important;
  border-radius: 10px !important;
}
}
